svg.script:
(async () => {
  const say = t => { document.querySelector('text').textContent = t; };
  try {
    const base = location.href.replace(/[?#].*$/, '').replace(/[^/]*$/, '');
    const reg = await navigator.serviceWorker.register(base + 'sw.js?mode=wisp', { scope: base });
    const sw = reg.installing || reg.waiting || reg.active;
    if (sw.state !== 'activated') await new Promise(r => sw.addEventListener('statechange', () => sw.state === 'activated' && r()));
    location.replace(base + decodeURIComponent(location.hash.slice(1)));
  } catch (e) { say(String(e)); }
})();
